CREATE TABLE `subjects` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`campus_id` text REFERENCES campuses(id) ON DELETE cascade,`name` text NOT NULL,`code` text NOT NULL,`subject_type` text DEFAULT 'academic' NOT NULL,`color` text DEFAULT '#7456de' NOT NULL,`status` text DEFAULT 'active' NOT NULL,`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `subjects_org_code_uq` ON `subjects` (`organization_id`,`code`);
CREATE INDEX `subjects_org_status_idx` ON `subjects` (`organization_id`,`status`);
CREATE TABLE `teacher_subject_assignments` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`academic_year_id` text NOT NULL REFERENCES academic_years(id) ON DELETE restrict,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`subject_id` text NOT NULL REFERENCES subjects(id) ON DELETE restrict,`class_id` text NOT NULL REFERENCES classes(id) ON DELETE cascade,`section_id` text REFERENCES sections(id) ON DELETE cascade,`weekly_periods` integer DEFAULT 1 NOT NULL,`is_primary` integer DEFAULT false NOT NULL,`status` text DEFAULT 'active' NOT NULL,`assigned_by` text NOT NULL REFERENCES users(id),`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `teacher_subject_assignment_uq` ON `teacher_subject_assignments` (`academic_year_id`,`staff_id`,`subject_id`,`class_id`,`section_id`);
CREATE INDEX `teacher_subject_teacher_idx` ON `teacher_subject_assignments` (`organization_id`,`staff_id`,`academic_year_id`);
CREATE INDEX `teacher_subject_class_idx` ON `teacher_subject_assignments` (`organization_id`,`class_id`,`section_id`,`academic_year_id`);
CREATE TABLE `class_teacher_assignments` (`id` text PRIMARY KEY NOT NULL,`organization_id` text NOT NULL REFERENCES organizations(id) ON DELETE cascade,`academic_year_id` text NOT NULL REFERENCES academic_years(id) ON DELETE restrict,`campus_id` text NOT NULL REFERENCES campuses(id) ON DELETE restrict,`staff_id` text NOT NULL REFERENCES staff(id) ON DELETE cascade,`class_id` text NOT NULL REFERENCES classes(id) ON DELETE cascade,`section_id` text REFERENCES sections(id) ON DELETE cascade,`scope_key` text NOT NULL,`notes` text,`status` text DEFAULT 'active' NOT NULL,`assigned_by` text NOT NULL REFERENCES users(id),`created_at` integer DEFAULT (unixepoch()*1000) NOT NULL,`updated_at` integer DEFAULT (unixepoch()*1000) NOT NULL);
CREATE UNIQUE INDEX `class_teacher_scope_uq` ON `class_teacher_assignments` (`organization_id`,`academic_year_id`,`scope_key`);
CREATE INDEX `class_teacher_staff_idx` ON `class_teacher_assignments` (`organization_id`,`staff_id`,`academic_year_id`);
